# Almacen asaltado (Ciudad Marea; contract 80; robbed house of Ciudad Marea: a villain grunt dug a tunnel through the wall and a man asks the hero to throw him out, then gives a disc), 9 x 7, interior,
# map id 232. column = i, row = j. A small harbour warehouse turned upside down: stacked crates along the back wall, barrels, a crate or two, the TUNNEL (a hole in the floor, `hole` object, look interaction) and the Vertice agent (trainer vertice_dig:
# facing S (a screen diagonal) he sees (4,2) and (5,3), not the door mat). A win = flag dig_agent (the owner's gate); the owner (script `owner`) then hands over Disc 32 (Cavar) once (flag dig_given = 693, the pick-up
# flag of the pouch that lay on Ciudad Marea's quay until contract 80, so an old save that took it keeps it taken); a full bag keeps the flag clear and he gives it at the next talk.
@map almacen_asaltado
@size 9 7
@interior yes
@flag dig_agent 231         # the Vertice beaten (his own beaten flag; the owner reads it)
@flag dig_given 693         # Disc 32 was handed over
@bg 3
@fill floor_wood
@spawn door 4 5 N
@legend
  .  tile=floor_wood
  C  tile=none object=wall_corner
  w  tile=none object=wall_j
  y  tile=none object=wall_win_j
  |  tile=none object=wall_i
  q  tile=none object=wall_win_i
  B  object=crate_stack interact=look text=extra.dig.shelf
  Z  object=barrel
  H  object=hole interact=look text=extra.dig.hole
  X  object=crate_plain
  V  npc=vertice id=agent face=S trainer=vertice_dig range=2 beaten_flag=dig_agent text=extra.dig.agent.pre after=extra.dig.agent.after
  O  npc=vecino_m id=owner face=E script=owner
  m  tile=mat
@grid
  Cwwywwyww
  |B.VHXB.B
  |........
  q......Z.
  |.O.....Z
  |........
  |...mm...
@warp m -> ciudad_marea spawn=almacen_door
# The owner: before beaten he begs the hero to throw the thief out; afterwards he thanks him and gives the disc (a full bag: next talk); then a last line.
@script owner npc
    npc_face_hero owner
    jf dig_given after
    jnf dig_agent wait
    say extra.dig.owner.thanks
    say gym.varo.disc
    give_item disc_32 1
    jv 0 0 full
    item_var 0 disc_32
    say gl.gift
    setf dig_given
    say extra.dig.owner.about
    end
  full:
    say gl.found.full
    end
  wait:
    say extra.dig.owner.wait
    end
  after:
    say extra.dig.owner.after
@end
